ocfs2: fix double unlock in case retry after free truncate
 log

If ocfs2_reserve_cluster_bitmap_bits() fails with ENOSPC, it will try to
free truncate log and then retry.  Since ocfs2_try_to_free_truncate_log
will lock/unlock global bitmap inode, we have to unlock it before
calling this function.  But when retry reserve and it fails with no
global bitmap inode lock taken, it will unlock again in error handling
branch and BUG.

This issue also exists if no need retry and then ocfs2_inode_lock fails.
So fix it.

Fixes: 2070ad1aebff ("ocfs2: retry on ENOSPC if sufficient space in truncate log")
Link: http://lkml.kernel.org/r/57D91939.6030809@huawei.com
Signed-off-by: Joseph Qi <joseph.qi@huawei.com>
Signed-off-by: Jiufei Xue <xuejiufei@huawei.com>
Cc: Mark Fasheh <mfasheh@suse.de>
Cc: Joel Becker <jlbec@evilplan.org>
Cc: Junxiao Bi <junxiao.bi@oracle.com>
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>
Signed-off-by: Linus Torvalds <torvalds@linux-foundation.org>

Here is the root cause:
The bug arises from improper handling of inode locking and unlocking during the retry mechanism in the `ocfs2_reserve_cluster_bitmap_bits` function. When the function fails with ENOSPC and attempts to free the truncate log, it does not correctly manage the locking state of the global bitmap inode. If the retry fails and the inode was not locked, the code attempts to unlock it again, leading to a double unlock scenario, which can cause a kernel BUG.

Here is the patch:
  * things a bit. */
 static int ocfs2_reserve_clusters_with_limit(struct ocfs2_super *osb,
 					     u32 bits_wanted, u64 max_block,
 					     int flags,
 					     struct ocfs2_alloc_context **ac)
 {
 	int status, ret = 0;
 	int retried = 0;

 	*ac = kzalloc(sizeof(struct ocfs2_alloc_context), GFP_KERNEL);
 	if (!(*ac)) {
 		status = -ENOMEM;
 		mlog_errno(status);
 		goto bail;
 	}

 	(*ac)->ac_bits_wanted = bits_wanted;
 	(*ac)->ac_max_block = max_block;

 	status = -ENOSPC;
 	if (!(flags & ALLOC_GROUPS_FROM_GLOBAL) &&
 	    ocfs2_alloc_should_use_local(osb, bits_wanted)) {
 		status = ocfs2_reserve_local_alloc_bits(osb,
 							bits_wanted,
 							*ac);
 		if ((status < 0) && (status != -ENOSPC)) {
 			mlog_errno(status);
 			goto bail;
 		}
 	}

 	if (status == -ENOSPC) {
 retry:
 		status = ocfs2_reserve_cluster_bitmap_bits(osb, *ac);
 		/* Retry if there is sufficient space cached in truncate log */
 		if (status == -ENOSPC && !retried) {
 			retried = 1;
 			ocfs2_inode_unlock((*ac)->ac_inode, 1);
 			inode_unlock((*ac)->ac_inode);

 			ret = ocfs2_try_to_free_truncate_log(osb, bits_wanted);
-			if (ret == 1)
+			if (ret == 1) {
+				iput((*ac)->ac_inode);
+				(*ac)->ac_inode = NULL;
 				goto retry;
+			}

 			if (ret < 0)
 				mlog_errno(ret);

 			inode_lock((*ac)->ac_inode);
-			ocfs2_inode_lock((*ac)->ac_inode, NULL, 1);
+			ret = ocfs2_inode_lock((*ac)->ac_inode, NULL, 1);
+			if (ret < 0) {
+				mlog_errno(ret);
+				inode_unlock((*ac)->ac_inode);
+				iput((*ac)->ac_inode);
+				(*ac)->ac_inode = NULL;
+				goto bail;
+			}
 		}
 		if (status < 0) {
 			if (status != -ENOSPC)
 				mlog_errno(status);
 			goto bail;
 		}
 	}

 	status = 0;
 bail:
 	if ((status < 0) && *ac) {
 		ocfs2_free_alloc_context(*ac);
 		*ac = NULL;
 	}

 	if (status)
 		mlog_errno(status);
 	return status;
 }



